import { StyleFn } from "..";

export const Divider: StyleFn = (theme, mode) => {
  const { color, size } = theme;

  return {
    root: {
      width: "auto",
      height: "auto",
      display: "block",
      border: 0,
      borderBottom: `1px solid ${color.border.neutral.default[mode]}`,
      margin: `${size.spacing[8]} 0`,
    },
    _vertical: {
      borderBottom: 0,
      borderLeft: `1px solid ${color.border.neutral.default[mode]}`,
      margin: `0 ${size.spacing[8]}`,
      boxSizing: "content-box",
      alignSelf: "stretch",
    },
    _inset: {
      marginLeft: `${size.spacing[16]}`,
      marginRight: `${size.spacing[16]}`,
    },
    _dense: {
      margin: 0,
    },
  };
};
